
import type { ServiceCategory, Service } from '@/types/services';

function slugify(text: string): string {
  return text
    .toString()
    .toLowerCase()
    .trim()
    .replace(/\s+/g, '-') // Replace spaces with -
    .replace(/[^\w-]+/g, '') // Remove all non-word chars
    .replace(/--+/g, '-'); // Replace multiple - with single -
}

const facialSurgeryServicesBase: Omit<Service, 'slug'>[] = [
  { id: 'op-hunde', name: 'Nose Surgery (Rhinoplasty)', categorySlug: 'facial-surgery', description: 'Rhinoplasty, commonly known as nose surgery, is a transformative procedure designed to reshape the nose, improving its appearance and proportion in relation to other facial features. It can address concerns such as nose size, width, bridge profile, tip shape, nostril size, and asymmetry. Beyond aesthetics, rhinoplasty can also correct structural defects like a deviated septum that may cause breathing problems. Our surgeons meticulously sculpt nasal bone and cartilage to achieve natural, harmonious results tailored to your unique facial structure. Explore if rhinoplasty is right for you during a detailed consultation at NexaSculpt Clinic.', image: '/images/woman-getting-ready-nose-job-surgery (1).jpg', imageHint: 'nose surgery detail' },
  { id: 'rim-hunde', name: 'Nose Tip Reshaping', categorySlug: 'facial-surgery', description: 'Nose tip reshaping, or tip-plasty, is a specialized form of rhinoplasty focusing specifically on refining the nasal tip. This procedure can correct a bulbous, drooping, upturned, or asymmetrical tip, enhancing the nose\'s overall definition and balance with the rest of the face. Techniques may involve cartilage sculpting, suturing, or grafting. It is ideal for patients primarily concerned with the appearance of their nasal tip rather than the entire nasal structure. Discover how targeted nose tip reshaping can refine your profile at NexaSculpt Clinic.', image: '/images/Nose Tip Reshaping.png', imageHint: 'nose tip surgery' },
  { id: 'rim-vesheve', name: 'Ear Reshaping (Otoplasty)', categorySlug: 'facial-surgery', description: 'Otoplasty, or ear reshaping surgery, is performed to correct the size, shape, or position of the ears. It commonly addresses protruding ears (pinning them closer to the head), overly large ears (macrotia), or misshapen ears due to injury or congenital conditions. The procedure involves sculpting ear cartilage to achieve a more natural and aesthetically pleasing appearance. Suitable for both adults and children (typically after age 5-6 when ears are nearly fully grown), otoplasty can significantly boost self-confidence. Learn about personalized otoplasty options at NexaSculpt Clinic.', image: '/images/otoplasty.png', imageHint: 'otoplasty results' },
  { id: 'mbj-flokeve', name: 'Hair Transplant', categorySlug: 'facial-surgery', description: 'Hair transplant surgery is a highly effective solution for hair loss, restoring hair to areas that are thinning or bald. The procedure involves harvesting healthy hair follicles from a donor area (typically the back or sides of the head) and meticulously implanting them into the recipient sites. Techniques like Follicular Unit Transplantation (FUT) or Follicular Unit Extraction (FUE) are used to achieve natural-looking density and hairline design. Results are permanent and grow like your natural hair. Find out about advanced hair transplant techniques and achieve a fuller head of hair at NexaSculpt Clinic.', image: '/images/hair-transplant.png', imageHint: 'hair transplant before after' },
  { id: 'mbj-mjekres', name: 'Beard Transplant', categorySlug: 'facial-surgery', description: 'A beard transplant enhances facial hair density, defines the beard shape, or fills in patchy areas on the cheeks, chin, and mustache area. Similar to scalp hair transplants, this procedure involves extracting hair follicles (usually from the back of the scalp) and implanting them into the beard region. It is an ideal solution for men seeking a fuller, more robust beard due to genetics, scarring, or previous hair removal. Achieve your desired beard aesthetic with our expert team at NexaSculpt Clinic.', image: '/images/Beard Transplant.png', imageHint: 'Beard Transplant results' },
  { id: 'mbj-vetullave', name: 'Eyebrow Transplant', categorySlug: 'facial-surgery', description: 'Eyebrow transplant surgery restores or enhances the fullness and shape of eyebrows that are thin, sparse, or scarred. Individual hair follicles are carefully extracted from a donor site (often the scalp) and implanted into the eyebrow region, following the natural growth pattern and desired arch. This procedure offers a permanent and natural-looking solution for beautifully defined eyebrows. Learn how an eyebrow transplant can frame your face and enhance your features at NexaSculpt Clinic.', image: '/images/Eyebrow Transplant.png', imageHint: 'eyebrow transplant detail' },
  { id: 'lift-vetullave', name: 'Eyebrow Lift (Browplasty)', categorySlug: 'facial-surgery', description: 'An eyebrow lift, or browplasty, rejuvenates the forehead and brow area by elevating sagging eyebrows and smoothing forehead wrinkles and frown lines. This procedure can create a more alert, youthful, and refreshed appearance, and may also improve vision if drooping brows obstruct the upper visual field. Various techniques, including endoscopic and traditional lifts, are tailored to individual needs. Explore brow lift options and their revitalizing benefits at NexaSculpt Clinic.', image: '/images/Eyebrow Lift (Browplasty).png', imageHint: 'eyebrow lift surgery' },
  { id: 'blefaroplastika', name: 'Eyelid Surgery (Blepharoplasty)', categorySlug: 'facial-surgery', description: 'Eyelid surgery, or blepharoplasty, is a procedure to improve the appearance of the eyelids. It can be performed on the upper lids, lower lids, or both. Upper blepharoplasty removes excess skin and fat that can cause hooding or impair vision. Lower blepharoplasty addresses puffiness, bags, and fine wrinkles under the eyes. The result is a more rested, youthful, and alert eye appearance. Discover how eyelid surgery can refresh your look and address functional concerns at NexaSculpt Clinic.', image: '/images/Eyelid Surgery (Blepharoplasty).png', imageHint: 'eyelid surgery results' },
  { id: 'lift-fytyres', name: 'Face Lift (Rhytidectomy)', categorySlug: 'facial-surgery', description: 'A facelift, or rhytidectomy, is a comprehensive surgical procedure designed to address significant signs of aging in the mid to lower face and neck. It involves lifting and tightening underlying facial muscles, repositioning fat, and removing excess skin to smooth deep wrinkles, reduce jowls, and restore more youthful facial contours. Tailored to individual needs, a facelift provides long-lasting, natural-looking rejuvenation. Learn about personalized facelift approaches and achieve a more youthful you at NexaSculpt Clinic.', image: '/images/Face Lift (Rhytidectomy).png', imageHint: 'face lift surgery' },
  { id: 'rim-mjekres', name: 'Chin Augmentation (Genioplasty)', categorySlug: 'facial-surgery', description: 'Chin augmentation, or genioplasty, enhances the size and projection of a recessed or "weak" chin, improving facial balance and profile harmony. This can be achieved through surgical insertion of a custom-fit chin implant or by repositioning the chin bone (sliding genioplasty). A well-defined chin can strengthen the jawline and create a more aesthetically pleasing facial structure. Discuss your chin augmentation options and desired outcomes with our specialists at NexaSculpt Clinic.', image: '/images/Chin Augmentation (Genioplasty).png', imageHint: 'chin augmentation surgery' },
];

const facialTreatmentsServicesBase: Omit<Service, 'slug'>[] = [
  { id: 'lip-reshaping', name: 'Lip Reshaping & Augmentation', categorySlug: 'facial-treatments', description: 'Lip reshaping and augmentation enhances lip volume, defines the lip border (vermilion border), corrects asymmetry, and smooths fine lines around the mouth. This is typically achieved using injectable dermal fillers, most commonly hyaluronic acid-based, which provide natural-looking and temporary results. The procedure is quick, with minimal downtime, offering an immediate improvement in lip contour and fullness. Explore customized lip enhancement techniques for your perfect pout at NexaSculpt Clinic.', image: '/images/Lip Reshaping & Augmentation.png', imageHint: 'lip fillers' },
  { id: 'xanthelasma-plasma-arc', name: 'Xanthelasma Removal (Plasma Arc)', categorySlug: 'facial-treatments', description: 'Xanthelasma removal using Plasma Arc technology is a precise, non-invasive treatment for yellowish cholesterol deposits that appear on or around the eyelids. The Plasma Arc device creates a tiny electrical arc that sublimates the targeted tissue without damaging surrounding skin. This method offers excellent cosmetic results with minimal scarring and downtime compared to traditional surgical excision. Learn about this effective and gentle removal method for xanthelasma at NexaSculpt Clinic.', image: '/images/Xanthelasma Removal (Plasma Arc).png', imageHint: 'xanthelasma plasma' },
  { id: 'multivitamin-treatment', name: 'Multivitamin Infusion Facial', categorySlug: 'facial-treatments', description: 'A Multivitamin Infusion Facial is a luxurious and highly effective treatment that delivers a potent cocktail of essential vitamins, antioxidants, and peptides directly into the skin. This nourishing infusion helps to combat signs of aging, brighten dull complexion, hydrate dry skin, and improve overall skin health and resilience. Tailored to your skin’s specific needs, this facial promotes a radiant, revitalized glow. Discover the rejuvenating benefits of targeted vitamin therapy for your skin at NexaSculpt Clinic.', image: '/images/Multivitamin Infusion Facial.png', imageHint: 'vitamin facial' },
  { id: 'eyelids-plasma-arc', name: 'Non-Surgical Eyelid Lift (Plasma Arc)', categorySlug: 'facial-treatments', description: 'A Non-Surgical Eyelid Lift using Plasma Arc technology, often called "fibroblast therapy," offers a minimally invasive alternative to surgical blepharoplasty for addressing mild to moderate sagging of the upper or lower eyelids. The plasma device creates a series of tiny dots on the skin, which triggers immediate skin tightening and stimulates long-term collagen production. This results in a lifted, more youthful eye appearance with reduced hooding and wrinkles. Find out if this innovative eyelid lift is suitable for you at NexaSculpt Clinic.', image: '/images/Non-Surgical Eyelid Lift (Plasma Arc).png', imageHint: 'plasma eyelid lift' },
  { id: 'cheekbone-reshaping', name: 'Cheekbone Contouring (Fillers)', categorySlug: 'facial-treatments', description: 'Cheekbone contouring with dermal fillers enhances the definition and volume of the cheekbones, restoring youthful contours or creating a more sculpted facial appearance. Strategically injected hyaluronic acid fillers can lift and support the mid-face, improve facial balance, and reduce the appearance of nasolabial folds. The procedure offers immediate results with minimal downtime. Learn about personalized cheekbone enhancement possibilities at NexaSculpt Clinic.', image: '/images/Cheekbone Contouring (Fillers).png', imageHint: 'cheek fillers' },
  { id: 'microdermabrasion', name: 'Microdermabrasion', categorySlug: 'facial-treatments', description: 'Microdermabrasion is a non-invasive skin resurfacing treatment that gently exfoliates the outermost layer of dead skin cells using a diamond-tipped wand or fine crystals. This process reveals smoother, brighter, and more even-toned skin. It helps to reduce the appearance of fine lines, minor scars, sun damage, and enlarged pores, while also stimulating collagen production for improved skin texture. Experience revitalized skin with microdermabrasion at NexaSculpt Clinic.', image: '/images/Microdermabrasion.png', imageHint: 'microdermabrasion skin' },
  { id: 'jawline-contouring', name: 'Jawline Contouring (Fillers/Threads)', categorySlug: 'facial-treatments', description: 'Jawline contouring aims to create a sharper, more defined, and youthful jawline. This can be achieved non-surgically using dermal fillers to add volume and structure, or with PDO threads to lift sagging skin and tighten the jowl area. These treatments can improve facial harmony, balance the profile, and reduce the appearance of a "double chin" or undefined jaw. Explore advanced jawline enhancement options at NexaSculpt Clinic.', image: '/images/Jawline Contouring FillersThreads.png', imageHint: 'jawline fillers' },
  { id: 'wrinkle-fillers', name: 'Dermal Fillers for Wrinkles', categorySlug: 'facial-treatments', description: 'Dermal fillers are injectable treatments designed to smooth out fine lines, moderate wrinkles, and deeper facial folds. Most commonly made from hyaluronic acid, these fillers work by restoring lost volume beneath the skin, plumping up creases and providing a more youthful appearance. They can be used on areas like nasolabial folds, marionette lines, and forehead lines. Discover various filler options for effective wrinkle reduction at NexaSculpt Clinic.', image: '/images/Dermal Fillers for Wrinkles.png', imageHint: 'dermal fillers face' },
  { id: 'prp-face', name: 'PRP Facial Rejuvenation', categorySlug: 'facial-treatments', description: 'PRP (Platelet-Rich Plasma) Facial Rejuvenation, also known as a "vampire facial," uses the healing properties of your own blood to stimulate skin renewal. A small blood sample is processed to concentrate platelets, which are rich in growth factors. This PRP is then microneedled or injected into the facial skin, promoting collagen production, improving skin texture and tone, reducing fine lines, and enhancing overall radiance. Learn about the natural benefits of PRP facials for skin revitalization at NexaSculpt Clinic.', image: '/images/PRP Facial Rejuvenation.png', imageHint: 'prp facial therapy' },
  { id: 'dark-circles-treatment', name: 'Under-Eye Dark Circles Treatment', categorySlug: 'facial-treatments', description: 'Under-eye dark circles and hollows can create a tired or aged appearance. Treatment options vary depending on the cause and may include dermal fillers (tear trough fillers) to restore volume, topical treatments with active ingredients like Vitamin K or retinol, chemical peels to improve skin tone, or laser therapy to address pigmentation. A personalized approach is key to effectively refreshing the under-eye area. Find tailored solutions for your under-eye concerns at NexaSculpt Clinic.', image: '/images/Under-Eye Dark Circles Treatment.png', imageHint: 'dark circles eye' },
  { id: 'prp-hair', name: 'PRP Hair Restoration', categorySlug: 'facial-treatments', description: 'PRP (Platelet-Rich Plasma) Hair Restoration is a non-surgical treatment for hair loss that involves injecting concentrated platelets from your own blood into the scalp. These platelets release growth factors that stimulate dormant hair follicles, promote new hair growth, increase hair thickness, and improve overall scalp health. It is a natural and safe option for both men and women experiencing hair thinning. Explore the potential of PRP for hair regrowth at NexaSculpt Clinic.', image: '/images/PRP Hair Restoration.png', imageHint: 'prp hair treatment' },
  { id: 'white-peeling', name: 'Chemical Peels (White Peeling)', categorySlug: 'facial-treatments', description: 'Chemical peels, including "White Peeling" or superficial peels, use mild acidic solutions (like glycolic acid, lactic acid, or salicylic acid) to gently exfoliate the outermost layer of the skin. This process removes dead skin cells, unclogs pores, improves skin tone and texture, reduces minor blemishes and pigmentation, and stimulates cell turnover for a brighter, smoother complexion. These peels are suitable for regular maintenance and addressing mild skin concerns. Discover the refreshing benefits of gentle chemical peels at NexaSculpt Clinic.', image: '/images/Chemical Peels (White Peeling).png', imageHint: 'chemical peel skin' },
  { id: 'microneedling', name: 'Microneedling (Collagen Induction Therapy)', categorySlug: 'facial-treatments', description: 'Microneedling, or Collagen Induction Therapy, is a minimally invasive procedure that uses a device with fine, sterile needles to create controlled micro-injuries in the skin. These micro-channels stimulate the body\'s natural wound healing process, boosting collagen and elastin production. This results in improved skin texture, reduced appearance of scars (including acne scars), fine lines, wrinkles, and enlarged pores, leading to firmer, more youthful-looking skin. Learn about the rejuvenating power of microneedling at NexaSculpt Clinic.', image: '/images/Microneedling (Collagen Induction Therapy).png', imageHint: 'microneedling device' },
  { id: 'radiofrequency-face', name: 'Radiofrequency Skin Tightening (Face)', categorySlug: 'facial-treatments', description: 'Radiofrequency (RF) Skin Tightening is a non-invasive treatment that uses RF energy to heat the deeper layers of the skin (dermis). This controlled heating causes collagen fibers to contract and stimulates the production of new collagen and elastin over time. The result is firmer, tighter, and smoother skin, with a reduction in fine lines and wrinkles. It\'s an excellent option for addressing skin laxity on the face and neck without surgery or downtime. Experience advanced facial skin tightening at NexaSculpt Clinic.', image: '/images/Radiofrequency Skin Tightening (Face).png', imageHint: 'radiofrequency facial' },
  { id: 'sulcus-filling', name: 'Nasolabial Fold Fillers (Sulcus Filling)', categorySlug: 'facial-treatments', description: 'Nasolabial folds, commonly known as smile lines or laugh lines, are the creases that run from the sides of the nose to the corners of the mouth. Dermal fillers, typically hyaluronic acid-based, can be skillfully injected into these folds to add volume, lift the skin, and soften their appearance. This treatment provides immediate, natural-looking results, restoring a smoother and more youthful contour to the mid-face. Effectively soften your smile lines with our expert injectors at NexaSculpt Clinic.', image: '/images/Nasolabial Fold Fillers (Sulcus Filling).png', imageHint: 'smile line fillers' },
  { id: 'chin-reshaping', name: 'Non-Surgical Chin Reshaping (Fillers)', categorySlug: 'facial-treatments', description: 'Non-surgical chin reshaping uses injectable dermal fillers to enhance the projection, shape, and definition of the chin without the need for surgery. This procedure can improve facial balance, strengthen a weak or recessed chin, and create a more harmonious profile. Hyaluronic acid fillers are carefully placed to achieve subtle yet impactful results, with minimal downtime. Achieve a more defined and balanced chin profile non-invasively at NexaSculpt Clinic.', image: '/images/Non-Surgical Chin Reshaping (Fillers).png', imageHint: 'chin fillers' },
];

const breastServicesBase: Omit<Service, 'slug'>[] = [
  { id: 'zmadh-gjoksit', name: 'Breast Augmentation', categorySlug: 'breasts', description: 'Breast augmentation, or mammoplasty, is a surgical procedure to increase breast size and enhance shape using saline or silicone implants, or through fat transfer. It can improve breast proportion, correct asymmetry, or restore volume lost after pregnancy or weight loss. Our surgeons work closely with you to select the appropriate implant type, size, and placement for beautiful, natural-looking results that align with your body and aesthetic goals. Explore your breast augmentation options and achieve the silhouette you desire at NexaSculpt Clinic.', image: '/images/Breast Augmentation.png', imageHint: 'breast augmentation' },
  { id: 'lift-gjoksit', name: 'Breast Lift', categorySlug: 'breasts', description: 'A breast lift, or mastopexy, raises and firms sagging breasts by removing excess skin and reshaping the underlying breast tissue and nipple-areola complex to a higher, more youthful position. This procedure is ideal for women experiencing breast ptosis (drooping) due to aging, pregnancy, breastfeeding, or weight fluctuations. A breast lift can restore a perkier, more youthful breast contour and can be combined with augmentation for enhanced volume. Discover how a breast lift can rejuvenate your profile at NexaSculpt Clinic.', image: '/images/Breast Lift.png', imageHint: 'breast lift' },
  { id: 'zvog-gjoksit', name: 'Breast Reduction', categorySlug: 'breasts', description: 'Breast reduction surgery, or reduction mammoplasty, alleviates the physical and emotional discomfort associated with overly large breasts (macromastia). The procedure involves removing excess breast tissue, fat, and skin to achieve a breast size more proportionate to your body. Benefits include relief from back, neck, and shoulder pain, improved posture, enhanced ability to participate in physical activities, and increased self-confidence. Learn about the transformative benefits of breast reduction surgery at NexaSculpt Clinic.', image: '/images/Breast Reduction.png', imageHint: 'breast reduction' },
  { id: 'rikonst-gjoksit', name: 'Breast Reconstruction', categorySlug: 'breasts', description: 'Breast reconstruction surgery aims to recreate the shape, appearance, and volume of a breast, most commonly after mastectomy or lumpectomy for breast cancer treatment, or for congenital deformities. Various techniques are available, including implant-based reconstruction and autologous tissue flap reconstruction (using your own body tissue). Our compassionate team provides personalized reconstruction plans to help restore wholeness and confidence. Discuss your breast reconstruction journey with our experts at NexaSculpt Clinic.', image: '/images/Breast Reconstruction.png', imageHint: 'breast reconstruction' },
];

const bodyServicesBase: Omit<Service, 'slug'>[] = [
  { id: 'lift-kraheve', name: 'Arm Lift', categorySlug: 'body', description: 'An arm lift, or brachioplasty, is a surgical procedure designed to remove excess sagging skin and fat from the upper arms, often referred to as "bat wings." This results in a firmer, more toned, and contoured arm appearance. It is ideal for individuals who have experienced significant weight loss or have loose skin due to aging. Achieve sleeker, more youthful arm contours and feel more confident in sleeveless attire with an arm lift at NexaSculpt Clinic.', image: '/images/Arm Lift.png', imageHint: 'arm lift' },
  { id: 'rim-barkut', name: 'Tummy Tuck', categorySlug: 'body', description: 'A tummy tuck, or abdominoplasty, is a surgical procedure that removes excess skin and fat from the abdomen and tightens weakened or separated abdominal muscles (diastasis recti). This results in a flatter, firmer, and more contoured midsection. It is particularly beneficial for individuals with loose skin after pregnancy or significant weight loss. Explore the transformative results of a full or mini tummy tuck procedure tailored to your needs at NexaSculpt Clinic.', image: '/images/Tummy Tuck.png', imageHint: 'tummy tuck' },
  { id: 'liposculptura', name: 'Liposculpture', categorySlug: 'body', description: 'Liposculpture is an advanced form of liposuction that not only removes unwanted fat deposits but also focuses on strategically sculpting and contouring specific body areas to enhance definition and proportion. It can be used to refine areas like the abdomen, flanks, thighs, arms, and neck. Our surgeons utilize precise techniques to achieve a more athletic and aesthetically pleasing silhouette. Refine your body shape with artistic liposculpture at NexaSculpt Clinic.', image: '/images/Liposculpture.png', imageHint: 'liposculpture body' },
  { id: 'rim-vitheve-bbl', name: 'BBL Buttock Remodeling', categorySlug: 'body', description: 'Buttock remodeling, often achieved through a Brazilian Butt Lift (BBL), enhances the size, shape, and projection of the buttocks using your body\'s own fat. Fat is harvested via liposuction from areas like the abdomen, back, or thighs, processed, and then strategically injected into the buttocks to create a fuller, rounder, and more lifted appearance. This procedure offers natural-looking and feeling results. Discover personalized BBL procedures for your desired buttock contour at NexaSculpt Clinic.', image: '/images/BBL Buttock Remodeling.png', imageHint: 'buttock remodel' },
  { id: 'labioplastika', name: 'Labiaplasty', categorySlug: 'body', description: 'Labiaplasty is a surgical procedure to alter the size or shape of the labia minora (inner lips) or labia majora (outer lips) of the vulva. It is often performed to address discomfort from enlarged labia during physical activities, improve hygiene, enhance aesthetic appearance, or boost self-confidence. Our surgeons provide compassionate and discreet care, tailoring the procedure to your specific needs and desired outcome. Discuss your concerns and labiaplasty options with our sensitive professionals at NexaSculpt Clinic.', image: '/images/Labiaplasty.png', imageHint: 'labiaplasty surgery' },
  { id: 'lift-kofsheve', name: 'Thigh Lift', categorySlug: 'body', description: 'A thigh lift, or thighplasty, is a surgical procedure to remove excess skin and fat from the inner and/or outer thighs, resulting in smoother, firmer, and more proportionate leg contours. It is ideal for individuals with loose, sagging thigh skin due to significant weight loss or aging. A thigh lift can improve comfort, confidence, and the fit of clothing. Achieve more toned and contoured thighs with a personalized lift procedure at NexaSculpt Clinic.', image: '/images/Thigh Lift.png', imageHint: 'thigh lift' },
  { id: 'gynecomastia', name: 'Gynecomastia', categorySlug: 'body', description: 'Gynecomastia surgery corrects enlarged male breast tissue, creating a flatter, firmer, and more masculine chest contour. The procedure may involve liposuction to remove excess fat, surgical excision to remove glandular breast tissue, or a combination of both. It is an effective solution for men who are self-conscious about the appearance of their chest. Address gynecomastia and restore your confidence with our expert surgical team at NexaSculpt Clinic.', image: '/images/Gynecomastia.png', imageHint: 'male chest' },
  { id: 'cellulite-treatment', name: 'Cellulite Treatment', categorySlug: 'body', description: 'Cellulite, characterized by dimpled or orange-peel skin texture, commonly appears on the thighs and buttocks. Our cellulite treatments aim to reduce its appearance and improve skin smoothness. Options may include minimally invasive procedures like subcision, energy-based devices (e.g., radiofrequency, laser), or injectable treatments that target the structural causes of cellulite. A consultation will determine the most effective approach for your specific type of cellulite. Explore personalized cellulite reduction strategies at NexaSculpt Clinic.', image: '/images/Cellulite Treatment.png', imageHint: 'cellulite reduction' },
  { id: 'plasma-arc-body', name: 'Plasma Arc (Body)', categorySlug: 'body', description: 'Plasma Arc technology, also known as fibroblast therapy, can be used for non-surgical skin tightening and rejuvenation on various body areas. It is effective for treating skin laxity, fine lines, stretch marks, and certain scars. The plasma device creates controlled micro-injuries that stimulate collagen production and promote tissue contraction, leading to firmer, smoother skin over time. Learn about the versatility of Plasma Arc for body skin concerns at NexaSculpt Clinic.', image: '/images/Plasma Arc (Body).png', imageHint: 'skin tightening body' },
  { id: 'carboxytherapy', name: 'Carboxytherapy', categorySlug: 'body', description: 'Carboxytherapy is a minimally invasive treatment involving the therapeutic administration of medical-grade carbon dioxide (CO2) gas into the subcutaneous tissue. This process improves local blood circulation, stimulates collagen production, enhances skin elasticity, and can help reduce the appearance of cellulite, stretch marks, and localized fat deposits. It is a safe procedure with minimal downtime. Discover the regenerative benefits of carboxytherapy for various skin and body concerns at NexaSculpt Clinic.', image: '/images/Carboxytherapy.png', imageHint: 'skin treatment' },
  { id: 'sclerotherapy', name: 'Sclerotherapy', categorySlug: 'body', description: 'Sclerotherapy is a highly effective medical procedure used to treat varicose veins and spider veins. It involves injecting a specialized sclerosing solution directly into the targeted veins. This solution irritates the lining of the vein, causing it to collapse, stick together, and eventually fade from view as the body absorbs it. Multiple sessions may be needed for optimal results. Find relief from unsightly and uncomfortable veins with sclerotherapy at NexaSculpt Clinic.', image: '/images/Sclerotherapy.png', imageHint: 'vein treatment' },
  { id: 'lipolysis', name: 'Lipolysis', categorySlug: 'body', description: 'Lipolysis refers to non-surgical fat reduction treatments designed to break down and eliminate localized, stubborn fat cells that are resistant to diet and exercise. Techniques can include injectable lipolysis (using deoxycholic acid-based solutions like Kybella) or energy-based devices (such as cryolipolysis/fat freezing, laser lipolysis, or radiofrequency lipolysis). These treatments offer a less invasive alternative to liposuction for body contouring. Target specific fat pockets and achieve a more sculpted physique with advanced lipolysis options at NexaSculpt Clinic.', image: '/images/Lipolysis.png', imageHint: 'fat reduction' },
  { id: 'laser-hair-removal', name: 'Laser Hair Removal', categorySlug: 'body', description: 'Laser hair removal offers a long-term solution for reducing unwanted hair on various parts of the face and body. The procedure uses concentrated light energy (laser) to target and damage hair follicles, inhibiting future hair growth. Multiple sessions are typically required for optimal results due to hair growth cycles. It is effective for most skin types and hair colors, providing smoother, hair-free skin. Achieve lasting smoothness and say goodbye to constant shaving or waxing with laser hair removal at NexaSculpt Clinic.', image: '/images/Laser Hair Removal.png', imageHint: 'hair removal' },
];

const aestheticDentistryServicesBase: Omit<Service, 'slug'>[] = [
  { id: 'teeth-whitening', name: 'Teeth Whitening', categorySlug: 'aesthetic-dentistry', description: 'Professional teeth whitening treatments effectively lighten the color of your teeth, removing stains and discoloration caused by food, drinks, smoking, or aging. We offer safe and efficient in-office or take-home whitening systems that deliver noticeable results, giving you a brighter, more confident smile. Achieve a dazzling smile with our expert teeth whitening services at NexaSculpt Clinic.', image: '/images/Teeth Whitening.png', imageHint: 'teeth whitening smile' },
  { id: 'composite-veneers', name: 'Composite Veneers', categorySlug: 'aesthetic-dentistry', description: 'Composite veneers are thin, custom-made shells of tooth-colored composite resin bonded directly to the front surface of teeth to improve their appearance. They can correct issues like chips, cracks, gaps, discoloration, or minor misalignment. This minimally invasive procedure is typically completed in a single visit and offers a cost-effective way to achieve a beautiful smile makeover. Transform your smile with expertly crafted composite veneers at NexaSculpt Clinic.', image: '/images/Composite Veneers.png', imageHint: 'dental veneers beautiful' },
  { id: 'emax-veneers', name: 'E-Max Veneers', categorySlug: 'aesthetic-dentistry', description: 'E-Max veneers are premium, high-strength lithium disilicate ceramic veneers renowned for their exceptional aesthetics, durability, and natural translucency. They are custom-fabricated to precisely fit your teeth and can dramatically improve color, shape, size, and alignment. E-Max veneers offer a long-lasting, stain-resistant solution for a stunning smile transformation. Discover the superior beauty and quality of E-Max veneers for your ultimate smile at NexaSculpt Clinic.', image: '/images/E-Max Veneers.png', imageHint: 'porcelain veneers smile' },
];

const prostheticsServicesBase: Omit<Service, 'slug'>[] = [
  { id: 'dental-crowns', name: 'Dental Crowns', categorySlug: 'prosthetics', description: 'Dental crowns, or "caps," are custom-made restorations that completely cover a damaged, weakened, or discolored tooth, restoring its strength, shape, size, and appearance. Crowns can be made from various materials like porcelain, ceramic, zirconia, or metal alloys. They are used to protect a tooth after root canal treatment, support a dental bridge, or cover a dental implant. Receive durable and aesthetically pleasing dental crowns at NexaSculpt Clinic.', image: '/images/Dental Crowns.png', imageHint: 'dental crown tooth' },
  { id: 'dental-bridges', name: 'Dental Bridges', categorySlug: 'prosthetics', description: 'Dental bridges are fixed restorations used to replace one or more missing teeth. They consist of an artificial tooth (pontic) fused between two or more crowns (abutments) that are placed on the natural teeth or dental implants adjacent to the gap. Bridges restore chewing function, maintain facial shape, prevent remaining teeth from shifting, and improve smile aesthetics. Restore your complete smile and function with custom dental bridges at NexaSculpt Clinic.', image: '/images/Dental Bridges.png', imageHint: 'dental bridge teeth' },
  { id: 'dentures', name: 'Dentures', categorySlug: 'prosthetics', description: 'Dentures are removable prosthetic devices designed to replace missing teeth and surrounding tissues. We offer full dentures (replacing all teeth in an arch) and partial dentures (replacing some missing teeth while utilizing remaining natural teeth for support). Modern dentures are custom-crafted for a comfortable fit and natural appearance, restoring oral function and improving your smile and confidence. Discuss comfortable and natural-looking denture solutions with our team at NexaSculpt Clinic.', image: '/images/Dentures.png', imageHint: 'dentures smile' },
];

const orthodonticsServicesBase: Omit<Service, 'slug'>[] = [
  { id: 'invisalign', name: 'Invisalign', categorySlug: 'orthodontics', description: 'Invisalign is a revolutionary orthodontic treatment that straightens teeth using a series of custom-made, clear, and removable aligners. These virtually invisible aligners gradually shift your teeth into their desired position without the need for metal brackets or wires. Invisalign offers a comfortable, discreet, and convenient way to achieve a beautifully aligned smile for both teens and adults. Discover the clear alternative to braces with Invisalign at NexaSculpt Clinic.', image: '/images/Invisalign.png', imageHint: 'invisalign aligners smile' },
  { id: 'fixed-braces', name: 'Fixed Braces', categorySlug: 'orthodontics', description: 'Fixed braces are a traditional and highly effective orthodontic treatment for correcting misaligned teeth, bite issues (like overbites or underbites), and jaw problems. They consist of metal or ceramic brackets bonded to the teeth and connected by archwires, which apply gentle, continuous pressure to move teeth into proper alignment. Suitable for complex cases in both children and adults, fixed braces achieve predictable and lasting results. Explore your options for optimal teeth alignment with fixed braces at NexaSculpt Clinic.', image: '/images/Fixed Braces.png', imageHint: 'dental braces smile' },
  { id: 'removable-appliances', name: 'Removable Appliances', categorySlug: 'orthodontics', description: 'Removable orthodontic appliances are custom-designed devices that can be taken in and out of the mouth by the patient. They serve various purposes, such as guiding jaw growth in children, correcting minor tooth movements, expanding the dental arch, or maintaining the results achieved after fixed brace treatment (retainers). Their effectiveness depends on consistent wear as prescribed by the orthodontist. Learn about the role of specific removable appliances in your orthodontic care plan at NexaSculpt Clinic.', image: '/images/Removable Appliances.png', imageHint: 'orthodontic appliance' },
];

const restorativeDentistryServicesBase: Omit<Service, 'slug'>[] = [
  { id: 'teeth-cleaning', name: 'Teeth Cleaning (Calculus Removal)', categorySlug: 'restorative-dentistry', description: 'Professional teeth cleaning, also known as prophylaxis or calculus (tartar) removal, is essential for maintaining optimal oral health. Our hygienists gently remove hardened plaque (calculus) and soft plaque from tooth surfaces and below the gumline, areas often missed by regular brushing and flossing. This helps prevent cavities, gum disease (gingivitis and periodontitis), and bad breath, leaving your teeth feeling smooth and polished. Maintain a healthy smile with regular professional cleanings at NexaSculpt Clinic.', image: '/images/Teeth Cleaning (Calculus Removal).png', imageHint: 'dental cleaning hygiene' },
  { id: 'dental-fillings', name: 'Dental Fillings', categorySlug: 'restorative-dentistry', description: 'Dental fillings are used to repair teeth damaged by decay (cavities), cracks, or fractures, restoring their normal function and shape. After removing the decayed portion of the tooth, the area is cleaned and filled with a durable material. Common filling materials include tooth-colored composite resin (for a natural look), amalgam (silver), or ceramic. Early detection and treatment of cavities with fillings can prevent further damage and more complex procedures. Get durable and aesthetic dental fillings to protect your teeth at NexaSculpt Clinic.', image: '/images/Dental Fillings.png', imageHint: 'tooth filling dental' },
  { id: 'root-canal-treatment', name: 'Root Canal Treatment', categorySlug: 'restorative-dentistry', description: 'Root canal treatment (endodontic therapy) is a procedure to treat infection or inflammation within the soft pulp tissue at the center of a tooth (the root canal system). This condition can be caused by deep decay, repeated dental procedures, or trauma. The infected pulp is removed, the inside of the tooth is cleaned and disinfected, and then filled and sealed. Root canal treatment saves the natural tooth, relieves pain, and prevents the spread of infection. Understand the tooth-saving benefits of root canal therapy at NexaSculpt Clinic.', image: '/images/Root Canal Treatment.png', imageHint: 'root canal procedure' },
];

const oralSurgeryServicesBase: Omit<Service, 'slug'>[] = [
  { id: 'tooth-extraction', name: 'Tooth Extraction', categorySlug: 'oral-surgery', description: 'Tooth extraction is the surgical removal of a tooth from its socket in the jawbone. Extractions may be necessary due to severe decay, advanced gum disease, infection, irreparable damage, impacted wisdom teeth, or to make space for orthodontic treatment. Our skilled dental surgeons perform both simple and surgical extractions with a focus on patient comfort and optimal healing. Experience gentle and professional tooth extractions when needed at NexaSculpt Clinic.', image: '/images/Tooth Extraction.png', imageHint: 'tooth extraction dental' },
  { id: 'dental-implants', name: 'Dental Implants', categorySlug: 'oral-surgery', description: 'Dental implants are advanced, biocompatible titanium posts surgically placed into the jawbone to serve as artificial tooth roots for replacing missing teeth. They provide a strong, stable foundation for fixed or removable replacement teeth (crowns, bridges, or dentures) that look, feel, and function like natural teeth. Implants help preserve jawbone structure, prevent teeth shifting, and offer a long-term solution for tooth loss. Discover the life-changing benefits of permanent tooth replacement with dental implants at NexaSculpt Clinic.', image: '/images/Dental Implants.png', imageHint: 'dental implant surgery' },
  { id: 'apical-resection', name: 'Apical Resection (Apicoectomy)', categorySlug: 'oral-surgery', description: 'An apical resection, or apicoectomy, is a specialized endodontic surgical procedure performed when a conventional root canal treatment has failed to resolve an infection at the tip of a tooth\'s root (apex). The procedure involves accessing the root tip through the gum, removing the infected tissue and the very end of the root, and then placing a filling to seal the root canal. This microsurgical technique can save a tooth that might otherwise require extraction. Learn about this advanced tooth-saving surgery from our specialists at NexaSculpt Clinic.', image: '/images/Apical Resection (Apicoectomy).png', imageHint: 'dental surgery procedure' },
];

const pediatricDentistryServicesBase: Omit<Service, 'slug'>[] = [
  { id: 'primary-teeth-care', name: 'Primary Teeth Care (Milk Teeth)', categorySlug: 'pediatric-dentistry', description: 'Primary teeth, or milk teeth, play a crucial role in a child\'s development, guiding the eruption of permanent teeth, aiding in speech, and facilitating proper chewing. Our pediatric dental care focuses on prevention, early detection of dental issues, and education for both children and parents. Services include regular check-ups, cleanings, fluoride treatments, and guidance on oral hygiene and diet, all delivered in a child-friendly environment. Ensure a healthy start for your child\'s lifelong oral health at NexaSculpt Clinic.', image: '/images/Primary Teeth Care (Milk Teeth).png', imageHint: 'child dentist kids' },
  { id: 'teeth-fluoridation', name: 'Teeth Fluoridation', categorySlug: 'pediatric-dentistry', description: 'Teeth fluoridation is a safe and effective preventive treatment that involves the professional application of fluoride to children\'s teeth. Fluoride strengthens tooth enamel, making it more resistant to acid attacks from plaque bacteria and sugars, thereby helping to prevent tooth decay (cavities). This treatment is particularly beneficial for children as their teeth are developing. Protect your child\'s precious smile with regular fluoride applications as part of their dental care at NexaSculpt Clinic.', image: '/images/Teeth Fluoridation.png', imageHint: 'fluoride treatment child' },
  { id: 'dental-sealants', name: 'Dental Sealants', categorySlug: 'pediatric-dentistry', description: 'Dental sealants are thin, protective plastic coatings applied to the chewing surfaces (pits and fissures) of children\'s back teeth (molars and premolars), where decay most often occurs. Sealants act as a barrier, sealing out food particles and bacteria, thus preventing cavities from forming in these vulnerable areas. The application is quick, painless, and can provide protection for many years. Safeguard your child\'s molars effectively with dental sealants at NexaSculpt Clinic.', image: '/images/Dental Sealants.png', imageHint: 'dental sealants kids' },
];


